use std :: borrow :: Cow ; use std :: fmt :: Write ; use std :: path :: PathBuf ; use convert_case :: { Case , Casing } ; use derive_setters :: Setters ; use forge_api :: { AgentId , Effort , ModelId , Usage } ; use nu_ansi_term :: { Color , Style } ; use reedline :: { Prompt , PromptHistorySearchStatus } ; use crate :: display_constants :: markers ; use crate :: utils :: humanize_number ; use nu_ansi_term :: Style ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Formats an [`Effort`] as its uppercase label, collapsing to the first three"] # [doc = " characters on narrow terminals (< [`WIDE_TERMINAL_THRESHOLD`] columns)."] fn effort_label (effort : & Effort , width : usize) -> String { let full = effort . to_string () . to_uppercase () ; if width >= WIDE_TERMINAL_THRESHOLD { full } else { full . chars () . take (3) . collect () } }